using System;using System.IO;using System.Text;using System.Threading;using System.IO.Compression;using System.Linq;using System.Text.RegularExpressions;using System.Windows.Forms;using System.Threading.Tasks;
internal static class AppLog {
 internal static string DirectoryPath{get{return Path.Combine(Engine.Store,"logs");}}
 internal static string Redact(string value){if(value==null)return "";string home=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);if(!String.IsNullOrEmpty(home))value=value.Replace(home,"%USERPROFILE%");return Regex.Replace(value,@"(?i)[A-Z]:\\Users\\[^\\\r\n]+",@"%USERPROFILE%");}
 internal static void Event(string category,string message){try{using(var gate=new Mutex(false,"Local\\WeixinThemeStudioLog")){bool held=false;try{try{held=gate.WaitOne(250);}catch(AbandonedMutexException){held=true;}if(!held)return;Directory.CreateDirectory(DirectoryPath);string file=Path.Combine(DirectoryPath,"events.log");if(File.Exists(file)&&new FileInfo(file).Length>1024*1024){for(int n=2;n>=1;n--){string from=file+"."+n,to=file+"."+(n+1);if(File.Exists(to))File.Delete(to);if(File.Exists(from))File.Move(from,to);}if(File.Exists(file+".1"))File.Delete(file+".1");File.Move(file,file+".1");}File.AppendAllText(file,DateTime.UtcNow.ToString("o")+" pid="+System.Diagnostics.Process.GetCurrentProcess().Id+" "+category+" "+Redact(message).Replace("\r"," ").Replace("\n"," | ")+Environment.NewLine,Encoding.UTF8);}finally{if(held)gate.ReleaseMutex();}}}catch{}}
 internal static void Error(string category,Exception e){Event(category,e.GetType().Name+": "+e.Message+" "+e.StackTrace);}
}
internal static class SupportReport {
 internal static string Snapshot(){var s=new StringBuilder();s.AppendLine("微信调色室 8.5 测试版诊断报告 / UTC "+DateTime.UtcNow.ToString("o"));s.AppendLine("仅诊断主题软件；不包含聊天、账号数据库、截图或壁纸图片。默认隐藏 Windows 用户目录；安装路径和其他技术路径可能保留。");s.AppendLine("Tool="+Application.ExecutablePath);s.AppendLine("RuntimeOS="+Environment.OSVersion+" x64="+Environment.Is64BitOperatingSystem+" CLR="+Environment.Version);s.AppendLine("AutoEnabled="+AutoBackground.Enabled+" Whole="+NativeBackground.WholeEnabled);try{s.AppendLine("Install="+Engine.Target);s.AppendLine("DLL size="+new FileInfo(Engine.Target).Length);s.AppendLine(NativeBackground.PaletteDiagnostic());}catch(Exception e){s.AppendLine("Live capture failed="+e);}
 foreach(string key in new[]{"process-monitor.txt","background-service.txt","background-worker.txt","auto-background.log","appearance-observed.txt","whole-background-plan.txt"}){s.AppendLine("--- "+key);try{s.AppendLine(ReadBounded(Path.Combine(Engine.Store,key),32768));}catch(Exception e){s.AppendLine("Unavailable="+e.Message);}}
 foreach(int mode in new[]{0,1})using(AppearanceProfiles.Use(mode)){s.AppendLine("--- appearance "+mode);foreach(string key in AppearanceProfiles.Keys){if(key.StartsWith("ink-")||key=="background-effects.txt"||key=="input-glass.txt"||key=="icon-effects.txt")try{s.AppendLine(key+"="+ReadBounded(AppearanceProfiles.Path(key),8192));}catch{s.AppendLine(key+"=not present");}}}return AppLog.Redact(s.ToString());}
 static string ReadBounded(string path,int limit){using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream,Encoding.UTF8,true)){var b=new char[limit];int n=reader.ReadBlock(b,0,b.Length);return new string(b,0,n)+(reader.Peek()>=0?"\n[truncated]":"");}}
 static void Entry(ZipArchive zip,string name,string value){using(var w=new StreamWriter(zip.CreateEntry(name).Open(),Encoding.UTF8))w.Write(value);}
 internal static void Export(string path){AppLog.Event("REPORT","Export requested");string stage=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var z=ZipFile.Open(stage,ZipArchiveMode.Create)){Entry(z,"报告.txt",Snapshot());Entry(z,"说明.txt","报告记录当前状态及近期事件。日志从6.7起积累，不能补回旧版历史；缺失与截断会在报告中标明。没有聊天内容、截图、壁纸或账号数据库。");foreach(string name in new[]{"prepared.json","state.json"}){string statePath=Path.Combine(NativeDeployment.Home,name);if(File.Exists(statePath))try{Entry(z,"native/"+name,AppLog.Redact(ReadBounded(statePath,65536)));}catch{}}
 foreach(string area in new[]{"versions","previews"}){string folder=Path.Combine(NativeDeployment.Home,area);if(Directory.Exists(folder))foreach(var dir in new DirectoryInfo(folder).GetDirectories().OrderByDescending(d=>d.LastWriteTimeUtc).Take(5))foreach(string name in new[]{"native-runtime.log","runtime.ini","applied.receipt","control-ready.txt"}){string file=Path.Combine(dir.FullName,name);if(File.Exists(file))try{Entry(z,"native/"+area+"/"+dir.Name+"/"+name,AppLog.Redact(ReadBounded(file,65536)));}catch{}}}
 if(Directory.Exists(AppLog.DirectoryPath))foreach(string file in Directory.GetFiles(AppLog.DirectoryPath,"events.log*").OrderBy(x=>x))try{Entry(z,"logs/"+Path.GetFileName(file),AppLog.Redact(ReadBounded(file,1100000)));}catch(Exception e){Entry(z,"logs/read-error.txt",AppLog.Redact(e.Message));}}if(File.Exists(path))File.Replace(stage,path,null);else File.Move(stage,path);AppLog.Event("REPORT","Export completed");}finally{if(File.Exists(stage))File.Delete(stage);}}
}
internal sealed partial class Studio {
 void AddReportControls(Panel p){WorkspaceNote(p,"日志与诊断报告",0,718,900,28);WorkspaceNote(p,"一键导出当前状态和近期错误，不包含聊天、账号或壁纸；可直接发回排查。",0,750,900,34);var export=WorkspaceButton(p,"导出诊断报告…",0,794,240);export.Click+=async delegate{using(var dialog=new SaveFileDialog{Filter="诊断报告 (*.zip)|*.zip",FileName="微信调色室诊断-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".zip"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;export.Enabled=false;try{status.Text="正在收集诊断，请稍候…";await Task.Run(()=>SupportReport.Export(dialog.FileName));status.Text="诊断报告已导出："+dialog.FileName;}catch(Exception e){AppLog.Error("REPORT",e);status.Text="导出失败："+e.Message;}finally{export.Enabled=true;}}};var folder=WorkspaceButton(p,"打开本地日志目录",260,794,240);folder.Click+=delegate{try{Directory.CreateDirectory(AppLog.DirectoryPath);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(AppLog.DirectoryPath){UseShellExecute=true});}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};p.Height=850;}
}

